<div class="pagehead"><div><span class="badge">RF-01 · Consultar catálogo</span><h1>Catálogo de libros</h1></div></div><form method="get" class="search"><input type="hidden" name="route" value="books"><input type="search" name="q" value="<?=e($q)?>" placeholder="Buscar por título, autor o categoría" aria-label="Buscar libros"><button>Buscar</button></form><div class="grid"><?php foreach($books as $b): ?><article class="book"><span class="tag"><?=e($b['category'])?></span><h2><?=e($b['title'])?></h2><p><?=e($b['author'])?></p><p><strong><?= (int)$b['available_copies']?></strong> disponibles</p><?php if(user()): ?><form method="post" action="<?=url('reserve')?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="book_id" value="<?=(int)$b['id']?>"><button <?=((int)$b['available_copies']===0?'disabled':'')?>>Reservar</button></form><?php else: ?><a class="button secondary" href="<?=url('login')?>">Ingresar para reservar</a><?php endif;?></article><?php endforeach;?></div><?php if(!$books): ?><p>No encontramos libros para esta búsqueda.</p><?php endif;?>
